    private function upsert(array $row): void
    {
        $baseId = null;

        if ($row['base_key'] !== null) {
            $baseId = KanaCharacter::where('script', $row['script'])
                ->where('romaji', $row['base_key'])
                ->where('type', 'gojuon')
                ->value('id');
        }

        KanaCharacter::updateOrCreate(
            // Identity = the letter's POSITION in the chart (script, type, row, column):
            // plain ASCII, unique per letter.
            //  - NOT (script, romaji, type): じ/ぢ ("ji") and ず/づ ("zu") share it, so
            //    ぢ/づ used to overwrite じ/ず.
            //  - NOT the character: MySQL's default collation (utf8mb4_unicode_ci)
            //    treats か = が = カ as EQUAL, so a lookup by character finds the wrong
            //    row and overwrites it (basic letters turned into dakuten ones).
            [
                'script' => $row['script'],
                'type' => $row['type'],
                'row' => $row['row'],
                'column' => $row['column'],
            ],
            [
                'character' => $row['character'],
                'romaji' => $row['romaji'],
                'base_character_id' => $baseId,
                'stroke_count' => $row['stroke_count'],
                'stroke_order' => $row['stroke_order'],
                'stroke_order_en' => $row['stroke_order_en'],
                'usage_note_id' => $row['usage_note_id'],
                'usage_note_en' => $row['usage_note_en'],
                'order' => $row['order'],
            ]
        );
    }
